(() => {
'use strict';
const app=document.getElementById('app');
const letters=[{char:'様',title:'接筆',copy:'線が接する部分',x:35,y:48},{char:'大',title:'線の突出',copy:'突出している線',x:50,y:24},{char:'京',title:'字中空間',copy:'「口」の内側の余白',x:50,y:47},{char:'永',title:'字の姿勢',copy:'文字全体の傾き',x:50,y:30},{char:'心',title:'線の性質',copy:'線の太さの違い',x:65,y:60}];
let preferences={name:'',email:'',motion:true};try{preferences={...preferences,...JSON.parse(localStorage.getItem('sanpitsu-preferences')||'{}')}}catch{}

const traits=[['線の突出','控えめ','大きい',72,'伸びやかな線','終わりの一画が文字の外へ伸びています'],['字中空間','狭い','広い',64,'ゆとりのある余白','文字の内側にほどよい空間があります'],['接筆','離れる','接する',38,'離して書く接点','線と線のあいだに小さな間が見られます'],['字の姿勢','左寄り','右寄り',57,'わずかな右傾き','文字全体が少し右に傾いています'],['線の性質','細い','太い',68,'存在感のある線','線の太さにはっきりとした表情があります']];
const handwritingSummary='線の端が長く伸び、文字の内側に広い空間があります。線同士の接点には隙間があり、全体はやや右に傾いています。';
const behaviorNotes=[
['線の突出','自分から働きかける','自分の考えを伝え、必要だと思ったことには自ら取り組むタイプです。周囲の反応を確かめながら進めることで、行動力を協力につなげられます。'],
['字中空間','異なる意見を受け止める','相手の意見を聞き、複数の選択肢を比較しながら考えることを大切にします。判断に迷うときは、自分が大切にしたい条件を先に決めると選びやすくなります。'],
['接筆','自分で確かめて判断する','周囲の意見をそのまま受け入れるより、自分で確かめて納得してから動こうとします。判断の理由を言葉にすると、相手と考えを共有しやすくなります。'],
['字の姿勢','人との関わりを行動につなげる','相手の反応に関心を持ち、対話の中で次の行動を見つけるのが得意です。相手に合わせる場面でも、自分のペースを確認する時間が役立ちます。'],
['線の性質','決めたことを続ける','自分が決めたことに力を注ぎ、途中で投げ出さずに取り組もうとします。状況が変わったときに進め方を見直すことで、粘り強さと柔軟さを両立できます。']
];
function behaviorSection(){return '<section class="behavior-section"><h2>行動特徴</h2>'+behaviorNotes.map(([axis,title,copy])=>'<section class="behavior-item"><h3 class="behavior-axis">'+axis+'</h3><p class="behavior-title">'+title+'</p><p>'+copy+'</p></section>').join('')+'</section>'}
let page='intro',letterIndex=0,records=[],activeRecord=null,strokes=[],drawingImage=null,homeTimer,loadingTimer,copyTimer,transitionTimer;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const icons={profile:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',pen:'<path d="m4 20 3-8L17 2l5 5-10 10-8 3ZM7 12l5 5M15 4l5 5"/>',book:'<path d="M5 3h14v18H5ZM9 3v18M12 8h4M12 12h4"/>',full:'<path d="M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6"/>'};
const svg=name=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+icons[name]+'</svg>';
function top(back){return '<header class="top">'+(back?'<button class="quiet" data-go="'+back+'">← 戻る</button>':'<button class="wordmark" data-go="home" aria-label="ホーム">三筆三様</button>')+'<div class="top-actions"><button class="icon-button" data-go="settings" aria-label="設定">'+svg('profile')+'</button></div></header>'}
function nav(){return '<nav class="nav" aria-label="メインナビゲーション">'+[['home','ホーム','home'],['input','診断','pen'],['history','記録','book']].map(([p,label,icon])=>'<button data-go="'+p+'" class="'+(page===p?'selected':'')+'" '+(page===p?'aria-current="page"':'')+'>'+svg(icon)+'<span>'+label+'</span></button>').join('')+'</nav>'}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(text){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.role='status';n.textContent=text;document.body.append(n);setTimeout(()=>n.remove(),4200)}
function go(next){clearInterval(homeTimer);clearTimeout(loadingTimer);clearTimeout(copyTimer);clearTimeout(transitionTimer);page=next;window.scrollTo(0,0);render()}
function render(){if(page==='intro')return intro();if(page==='loading')return loading();app.innerHTML='<div class="screen-scroll"><section class="app-page page-'+page+'">'+top(page==='result'?'history':page==='settings'?'home':null)+(page==='home'?home():page==='input'?input():page==='result'?result():page==='settings'?settings():history())+'</section></div>'+nav();if(page==='home'){if(!reduced&&preferences.motion)homeTimer=setInterval(()=>changeLetter(1),7600)}if(page==='input')setupInput();if(page==='settings')setupSettings()}
function intro(){app.innerHTML='<section class="intro intro-static"><div class="intro-title"><h1>三筆三様</h1><button class="line-button start" data-go="home">筆跡から自分を知る</button></div></section>'}
function glyph(char){const l=letters[letterIndex];return '<div class="glyph" aria-hidden="true" style="--fx:'+l.x+'%;--fy:'+l.y+'%"><span class="defocused">'+char+'</span><span class="focused">'+char+'</span></div>'}
function home(){const l=letters[letterIndex];return '<div class="home-title"><h1 style="margin-top:15px">文字の特徴を見る</h1></div><div class="lens" aria-label="'+l.char+'"><div class="lens-ring"></div>'+glyph(l.char)+'</div><div class="letter-copy"><h2>'+l.title+'</h2><p>'+l.copy.replace('\n','<br>')+'</p></div><div class="letter-controls"><button data-action="prev" aria-label="前の文字">‹</button><span data-letter-count>0'+(letterIndex+1)+' / 05</span><button data-action="next" aria-label="次の文字">›</button></div><div class="home-footer"><button class="line-button" data-go="input">筆跡を診断する<span class="arrow">→</span></button></div>'}
function changeLetter(step){if(page!=='home')return;clearTimeout(copyTimer);clearTimeout(transitionTimer);const lens=app.querySelector('.lens'),old=lens.querySelector('.glyph');lens.querySelectorAll('.glyph').forEach(n=>{if(n!==old)n.remove()});letterIndex=(letterIndex+step+letters.length)%letters.length;const l=letters[letterIndex];old.classList.add('out');lens.insertAdjacentHTML('beforeend',glyph(l.char));const incoming=lens.lastElementChild;incoming.classList.add('in');requestAnimationFrame(()=>requestAnimationFrame(()=>incoming.classList.remove('in')));lens.setAttribute('aria-label',l.char);const copy=app.querySelector('.letter-copy');copy.style.opacity=0;copyTimer=setTimeout(()=>{if(page!=='home')return;copy.innerHTML='<h2>'+l.title+'</h2><p>'+l.copy.replace('\n','<br>')+'</p>';copy.style.opacity=1;app.querySelector('[data-letter-count]').textContent='0'+(letterIndex+1)+' / 05'},reduced?0:600);transitionTimer=setTimeout(()=>old.remove(),reduced?0:1900)}
function input(){return '<h1 style="margin-top:12px">筆跡診断</h1><p class="input-instruction">枠内に「様」を書くか写真を選んでください</p><div class="drawing"><canvas width="800" height="800" aria-label="様を書くエリア"></canvas><div class="draw-hint">「様」を書いてください</div></div><div class="actions"><button data-action="clear">書き直す</button><button data-action="upload">写真を読み込む</button></div><input type="file" accept="image/*" hidden><div class="input-footer"><button class="line-button" data-action="analyze" disabled>診断する<span class="arrow">→</span></button><p class="tiny">体験版・サンプル診断</p><p class="error" role="alert"></p></div>'}
function setupInput(){const c=app.querySelector('canvas'),ctx=c.getContext('2d'),hint=app.querySelector('.draw-hint'),analyze=app.querySelector('[data-action="analyze"]');strokes=[];drawingImage=null;let down=false,currentStroke=null;ctx.strokeStyle='#232b78';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';function p(e){let b=c.getBoundingClientRect();return [+(800*(e.clientX-b.left)/b.width).toFixed(2),+(800*(e.clientY-b.top)/b.height).toFixed(2)]}function ready(){hint.hidden=true;hint.style.display='none';analyze.disabled=false}c.onpointerdown=e=>{if(e.button!==0)return;down=true;c.setPointerCapture(e.pointerId);currentStroke=[p(e)];strokes.push(currentStroke);ctx.beginPath();ctx.moveTo(...currentStroke[0]);ctx.lineTo(currentStroke[0][0]+.01,currentStroke[0][1]+.01);ctx.stroke();ready()};c.onpointermove=e=>{if(!down)return;const point=p(e);currentStroke.push(point);ctx.lineTo(...point);ctx.stroke()};c.onpointerup=c.onpointercancel=()=>{down=false};app.querySelector('[data-action="clear"]').onclick=()=>{ctx.clearRect(0,0,800,800);strokes=[];drawingImage=null;hint.hidden=false;hint.style.display='grid';analyze.disabled=true;app.querySelector('input').value='';app.querySelector('.error').textContent=''};const file=app.querySelector('input');app.querySelector('[data-action="upload"]').onclick=()=>file.click();file.onchange=()=>{if(!file.files[0])return;const url=URL.createObjectURL(file.files[0]),img=new Image();img.onload=()=>{ctx.clearRect(0,0,800,800);const s=Math.min(740/img.width,740/img.height);ctx.drawImage(img,(800-img.width*s)/2,(800-img.height*s)/2,img.width*s,img.height*s);strokes=[];ready();URL.revokeObjectURL(url)};img.onerror=()=>{URL.revokeObjectURL(url);app.querySelector('.error').textContent='画像を読み込めませんでした別の写真を選んでください'};img.src=url};analyze.onclick=()=>{const small=document.createElement('canvas');small.width=360;small.height=360;small.getContext('2d').drawImage(c,0,0,360,360);drawingImage=small.toDataURL('image/png');go('loading')}}
function loading(){let paths='';if(strokes.length){const total=strokes.length;paths='<svg class="writing" viewBox="0 0 800 800" aria-label="書いた文字をなぞっています">'+strokes.map((s,i)=>'<path pathLength="1" style="stroke-width:4;animation-duration:'+Math.max(.1,3.2/total)+'s;animation-delay:'+(i*3.2/total)+'s" d="M'+s.map(p=>p.join(',')).join(' L')+'"/>').join('')+'</svg>'}else{paths='<svg class="writing" viewBox="0 0 240 240" aria-label="文字が描かれています"><defs><clipPath id="write-mask"><rect width="240" height="0"><animate attributeName="height" from="0" to="240" dur="3.5s" fill="freeze"/></rect></clipPath></defs><text x="120" y="190" text-anchor="middle" clip-path="url(#write-mask)">様</text></svg>'}app.innerHTML='<section class="loading-page">'+paths+'<h1>筆跡を分析しています</h1></section>';loadingTimer=setTimeout(()=>{activeRecord={id:Date.now(),date:new Date().toISOString(),image:drawingImage};records.unshift(activeRecord);go('result')},4200)}
function result(){return '<div class="result-top"><div><h1 style="margin-top:12px">あなたの筆跡</h1></div><span class="sample">サンプル診断</span></div><div class="specimen">'+(activeRecord?.image?'<img src="'+activeRecord.image+'" alt="あなたが書いた様">':'<span class="sample-char">様</span>')+'</div><section class="result-summary"><h2>筆跡の特徴</h2><p class="summary-lines">'+handwritingSummary+'</p></section><div class="axes">'+traits.map((t,i)=>'<section class="axis reveal"><div class="axis-head"><h3><span class="num">0'+(i+1)+'</span>'+t[0]+'</h3></div><div class="scale '+(t[3]<50?'toward-left':'toward-right')+'" style="--bar-start:'+Math.min(50,t[3])+'%;--bar-width:'+Math.abs(t[3]-50)+'%" role="img" aria-label="'+t[0]+'：'+t[4]+'サンプル"></div><div class="poles"><span>'+t[1]+'</span><span>'+t[2]+'</span></div></section>').join('')+'</div>'+behaviorSection()+'<div class="result-buttons"><button class="line-button" data-go="history">筆跡記録を見る<span class="arrow">→</span></button><button class="quiet" data-go="input">もう一度診断する</button></div>'}
function history(){return '<h1 style="margin-top:12px">筆跡記録</h1>'+(records.length?'<section class="history-summary"><h2>これまでの傾向</h2><h3 class="category-heading">筆跡の特徴</h3><p>'+handwritingSummary+'</p><h3 class="category-heading">行動の特徴</h3><p>自分から行動し、相手の意見も取り入れながら考えるタイプです。納得してから判断し、決めたことには粘り強く取り組みます。</p></section><div class="history-label"><h2>履歴</h2><span class="tiny">'+records.length+'件</span></div>'+records.map((r,i)=>'<button class="history-row" data-record="'+r.id+'"><img class="history-thumb" src="'+r.image+'" alt="記録した文字のサムネイル"><div><h3>「様」の診断結果</h3><p>'+new Date(r.date).toLocaleString('ja-JP',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'})+' · サンプル</p></div><span class="arrow">→</span></button>').join(''):'<section class="history-summary"><h2>記録はまだありません</h2><p></p></section><button class="line-button" data-go="input">筆跡診断を始める<span class="arrow">→</span></button>')+'<p class="tiny" style="margin-top:25px">記録は再読み込みで消去されます</p>'}
function settings(){return '<h1>設定</h1><form id="preferences"><fieldset><legend>プロフィール</legend><label>名前<input name="name" maxlength="40" autocomplete="nickname" value="'+escapeHTML(preferences.name)+'"></label></fieldset><fieldset><legend>アカウント情報</legend><label>メールアドレス<input name="email" type="email" autocomplete="email" value="'+escapeHTML(preferences.email)+'"></label><p class="tiny">体験版・この端末内に保存</p></fieldset><fieldset><legend>表示設定</legend><label class="toggle-row">文字の自動切り替え<input name="motion" type="checkbox" '+(preferences.motion?'checked':'')+'></label></fieldset><button type="submit" class="line-button">変更を保存<span class="arrow">→</span></button><p id="save-status" role="status" class="tiny"></p></form>'}
function setupSettings(){app.querySelector('form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;const next={name:form.elements.name.value.trim(),email:form.elements.email.value.trim(),motion:form.elements.motion.checked};try{localStorage.setItem('sanpitsu-preferences',JSON.stringify(next));preferences=next;app.querySelector('#save-status').textContent='保存しました'}catch{app.querySelector('#save-status').textContent='保存できませんでした'}}}
app.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go){go(b.dataset.go);return}if(b.dataset.record){activeRecord=records.find(r=>r.id===Number(b.dataset.record));go('result');return}switch(b.dataset.action){case 'prev':case 'next':clearInterval(homeTimer);changeLetter(b.dataset.action==='next'?1:-1);if(!reduced&&preferences.motion)homeTimer=setInterval(()=>changeLetter(1),7600);break;case 'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('このブラウザでは画面収録機能をご利用ください')}catch{toast('このブラウザでは全画面表示を利用できません')}break}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_handwriting_app',description:'Open the home, handwriting input, or history screen.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['home','input','history']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['home','input','history'].includes(input.screen))throw new Error('Invalid screen');go(input.screen);return {screen:page,recordCount:records.length}}})).catch(()=>{})}catch{}}
render();
})();
